package com.sumedha.commerce.auth.security;
import com.sumedha.commerce.auth.config.AuthProperties; import com.sumedha.commerce.auth.entity.User; import io.jsonwebtoken.JwtException; import org.junit.jupiter.api.Test; import java.time.Duration; import static org.junit.jupiter.api.Assertions.*;
class JwtServiceTest { private final JwtService jwt=new JwtService(new AuthProperties("12345678901234567890123456789012",Duration.ofMinutes(5),Duration.ofDays(1),"test-issuer")); @Test void createsSignedTokenWithSubjectRoleAndIssuer(){User user=new User("customer@example.test","hash");var claims=jwt.parse(jwt.create(user)).getPayload();assertEquals(user.getId().toString(),claims.getSubject());assertEquals("CUSTOMER",claims.get("role"));assertEquals("test-issuer",claims.getIssuer());assertNotNull(claims.getIssuedAt());assertNotNull(claims.getExpiration());} @Test void rejectsMalformedToken(){assertThrows(JwtException.class,()->jwt.parse("not-a-jwt"));}}
